   const draw=(context,col,x,y,size,settings)=>{if(atlas){if(info.layout==='skill-2x2-v1')BattleSpriteAtlas.drawFrame(context,atlas,row,col,x,y,size,settings);else BattleSpriteAtlas.draw(context,atlas,row,col/3,x,y,size,settings);}else if(image){const fit=MotionMaterial.size(image.width,image.height,size,box.height,9);context.save();context.imageSmoothingEnabled=false;context.globalAlpha=settings.alpha;context.translate(Math.round(x),Math.round(y));context.drawImage(image,-fit.w/2,-fit.h/2,fit.w,fit.h);context.restore();}};
   const fragment=(context,i,x,y,size,settings)=>{const source=atlas?.canvas||image;if(!source)return;const w=atlas?atlas.tile:image.width,h=atlas?atlas.tile:image.height,sx=atlas?2*w:0,sy=atlas?row*h:0,x0=Math.floor(i%3*w/3),y0=Math.floor(Math.floor(i/3)%3*h/3),cw=Math.floor((i%3+1)*w/3)-x0,ch=Math.floor((Math.floor(i/3)%3+1)*h/3)-y0;if(cw<=0||ch<=0)return;context.save();context.imageSmoothingEnabled=false;context.globalAlpha=settings.alpha;context.translate(Math.round(x),Math.round(y));context.rotate(settings.angle);context.drawImage(source,sx+x0,sy+y0,cw,ch,-size/2,-size/2,size,size);context.restore();};
